import XCTest
@testable import Loonext

/// #719: the index and the search are the shared ones.
///
/// `Fixtures/settings-search-fixture.json` was generated by reading
/// packages/shared/src/settings-search.ts: the entries from its text, the
/// search vectors by running its `searchSettings`. Regenerate it when that file
/// changes. Passing here means this phone finds the same settings, in the same
/// order, as the web does for the same words.
final class SettingsSearchParityTests: XCTestCase {
    private struct FixtureEntry: Decodable {
        let id: String
        let section: String
        let anchor: String
        let page: String?
        let en: [String]
        let fr: [String]
    }

    private struct Vector: Decodable {
        let query: String
        let locale: String
        let visible: String
        let ids: [String]
    }

    private struct Sections: Decodable {
        let all: [String]
        let member: [String]
    }

    private struct Fixture: Decodable {
        let sections: Sections
        let index: [FixtureEntry]
        let vectors: [Vector]
    }

    private func fixture() throws -> Fixture {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/settings-search-fixture.json")
        return try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }

    func testTheIndexEqualsTheSharedOneEntryForEntry() throws {
        let fixture = try fixture()
        XCTAssertGreaterThan(fixture.index.count, 50, "the fixture is empty")
        XCTAssertEqual(fixture.index.count, SettingsSearchIndex.entries.count)
        for (shared, here) in zip(fixture.index, SettingsSearchIndex.entries) {
            XCTAssertEqual(shared.id, here.id)
            XCTAssertEqual(shared.section, here.section)
            XCTAssertEqual(shared.page, here.page)
            XCTAssertEqual(shared.en, here.en, "\(shared.id) en")
            XCTAssertEqual(shared.fr, here.fr, "\(shared.id) fr")
        }
    }

    func testEverySearchGivesTheSharedAnswer() throws {
        let fixture = try fixture()
        XCTAssertGreaterThan(fixture.vectors.count, 20, "no vectors")
        XCTAssertTrue(
            fixture.vectors.contains { !$0.ids.isEmpty },
            "every vector is empty, so this would pass for the wrong reason"
        )
        for vector in fixture.vectors {
            let visible = Set(vector.visible == "member" ? fixture.sections.member : fixture.sections.all)
            let got = searchSettings(vector.query, locale: vector.locale) { visible.contains($0) }
                .map(\.entry.id)
            XCTAssertEqual(got, vector.ids, "\"\(vector.query)\" (\(vector.locale), \(vector.visible))")
        }
    }

    func testTimeZoneIsFoundInEveryPlaceItIsSet() {
        let ids = searchSettings("time zone", locale: "en") { _ in true }.map(\.entry.id)
        for id in ["workspace:time-zone", "hours:business-hours", "hours:closed-dates"] {
            XCTAssertTrue(ids.contains(id), id)
        }
    }

    private func visible(for role: String) -> [SettingsSection] {
        SettingsSection.allCases.filter { section in
            section.needs == Capability.workspaceAccess || MemberRole.has(role, section.needs)
        }
    }

    func testAMemberNeverFindsAnOwnerOnlySetting() {
        let member = visible(for: "member")
        let zone = searchPhoneSettings("time zone", locale: "en", visible: member)
        XCTAssertTrue(zone.allSatisfy { $0.entry.section != "workspace" && $0.entry.section != "hours" })
        // Their own settings are still found.
        XCTAssertFalse(searchPhoneSettings("password", locale: "en", visible: member).isEmpty)
        // An owner finds the workspace one.
        let owner = searchPhoneSettings("time zone", locale: "en", visible: visible(for: "owner"))
        XCTAssertTrue(owner.contains { $0.entry.id == "workspace:time-zone" })
    }

    func testAResultCarriesItsGroupAndSectionAndHoursStaysApartFromAutomaticTexts() throws {
        let owner = visible(for: "owner")
        let away = try XCTUnwrap(
            searchPhoneSettings("away reply", locale: "en", visible: owner)
                .first { $0.entry.anchor == "away-reply" }
        )
        XCTAssertEqual(away.section, .hours)
        XCTAssertEqual(away.group, .messages)
        let rating = try XCTUnwrap(
            searchPhoneSettings("rating", locale: "en", visible: owner)
                .first { $0.entry.anchor == "auto-text-rating" }
        )
        XCTAssertEqual(rating.section, .automaticTexts)
    }

    /// An entry pointing at nothing: every `anchor: "…"` a settings card carries
    /// must be in the index, and no two cards may claim the same one.
    func testEveryCardAnchorIsInTheIndexAndUsedOnce() throws {
        let features = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent() // LoonextTests
            .deletingLastPathComponent() // ios
            .appendingPathComponent("Loonext/Features")
        guard let walker = FileManager.default.enumerator(at: features, includingPropertiesForKeys: nil) else {
            return XCTFail("Features sources not found at \(features.path)")
        }
        let pattern = try NSRegularExpression(pattern: #"SettingsCard\([^{]*?anchor: "([a-z0-9-]+)""#, options: [.dotMatchesLineSeparators])
        var used: [String] = []
        for case let file as URL in walker where file.pathExtension == "swift" {
            let source = try String(contentsOf: file, encoding: .utf8)
            let range = NSRange(source.startIndex..., in: source)
            for match in pattern.matches(in: source, range: range) {
                if let r = Range(match.range(at: 1), in: source) { used.append(String(source[r])) }
            }
        }
        XCTAssertGreaterThan(used.count, 30, "the scan found no anchors")
        let known = Set(SettingsSearchIndex.entries.map(\.anchor))
        XCTAssertEqual(used.filter { !known.contains($0) }, [], "anchors with no index entry")
        XCTAssertEqual(
            Dictionary(grouping: used, by: { $0 }).filter { $0.value.count > 1 }.keys.sorted(),
            [],
            "anchors on two cards"
        )
    }
}
